def _apply_cached_indexes(self, cached_indexes, persist=False):
        """Reassign various resampler index attributes."""
        for attr in ["index", "index_freq", "index_freq_str", "index_asof"]:
            setattr(self, attr, cached_indexes[attr])

        if persist:
            self._cached_indexes = cached_indexes

